  const state={lang:localStorage.getItem('ass-lang')==='de'?'de':'it',session:{},overview:{rooms:[],matches:[],tournaments:[]},data:null,view:'home',id:null,busy:false,poll:null,fingerprint:'',request:0,tournamentTab:'fixtures',animating:false,playback:null,polling:false};
