    const before=state.fingerprint;state.polling=true;
    try{const data=await api(`/api/${type}/${encodeURIComponent(state.id)}`);if(serial!==state.request||state.busy||state.animating||before!==state.fingerprint)return;const fingerprint=JSON.stringify(data);if(state.fingerprint!==fingerprint){const focused=document.activeElement;if(focused&&$('#main').contains(focused)&&/INPUT|SELECT|TEXTAREA/.test(focused.tagName))return;if(type==='rooms')await presentRoom(data,serial);else{state.data=data;state.fingerprint=fingerprint;render();}}$('.online-indicator span').textContent=t('ready');}
